def find_top_2(arr):
    """
    Finds the top-2 most occurring elements in an integer array using the Boyer-Moore Voting Algorithm.
    """
    if len(arr) < 2:
        return None, None

    count_dict = {}
    for num in arr:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    max_count = max(count_dict.values())
    candidates = [k for k, v in count_dict.items() if v == max_count]

    if len(candidates) < 2:
        return candidates[0], None

    count_dict = {k: count_dict[k] for k in candidates}
    for num in arr:
        if num in count_dict:
            count_dict[num] -= 1
        if num not in candidates:
            continue
        if count_dict[num] == 0:
            candidates.remove(num)

    if len(candidates) == 1:
        return candidates[0], None

    second_candidate = max(set(count_dict), key=count_dict.get)
    return candidates[0], second_candidate
```

